export const ARTICLES: Article[] = [...RAW, ...MORE].map((article, index) => ({
  ...article,
  publishedAt: publishedAt(index),
}));

export function publishedArticles(): Article[] {
  return ARTICLES;
}

export function articleBySlug(slug: string): Article | null {
  return ARTICLES.find((article) => article.slug === slug) ?? null;
}

export function relatedArticles(slug: string): Article[] {
  const list = ARTICLES;
  const index = list.findIndex((article) => article.slug === slug);
  if (index < 0) return [];
  const related: Article[] = [];
  for (let step = 1; related.length < 3 && step < list.length; step += 1) related.push(list[(index + step) % list.length]);
  return related;
}
